python - <<'PY'
from pathlib import Path
root=Path('/workspaces/semio')
bundles=[]
for tech in ['coda','semio','repo','elements']:
    t=root/tech
    if not t.exists():
        continue
    for d in sorted(t.iterdir()):
        if d.is_dir() and (d/'README.md').exists():
            bundles.append((tech,d.name,d))

def kind_for(name):
    ui_like={'ui','desktop','vscode','studio','sketchpad','sites'}
    if name in ui_like:
        return 'ui','🖱️'
    if name in {'assets'}:
        return 'assets','🏪'
    if name in {'examples'}:
        return 'example','📔'
    if name in {'jsonschema','graphql','openapi','antlr','rdf'}:
        return 'schema','🛂'
    if name in {'go','engine','server','postgres','sqlite','py','rb','rs','net','gh','peg','3dm','algorithms','liveblocks','blnbo','programming'}:
        return 'library','📚'
    return 'library','📚'

for tech,name,path in bundles:
    kind,emoji=kind_for(name)
    description=f'The {name} bundle for {tech}.'
    content='''---
technology: {tech}
bundle:
 name: {name}
 emoji: {emoji}
 description: {description}
 kind: {kind}
---

# 🧾 Specification

## 🕸️ Systems

## 🧮 Algorithms

## 🛠️ Mechanisms

## 📛 Entities
'''.format(tech=tech,name=name,emoji=emoji,description=description,kind=kind)
    (path/'AGENTS.md').write_text(content)
print(f'updated {len(bundles)} bundle AGENTS.md files')
PY

