import os
root='/workspaces/semio'
techs=['coda','semio','repo','elements']
missing=[]
for tech in techs:
    t=os.path.join(root,tech)
    for name in sorted(os.listdir(t)):
        p=os.path.join(t,name)
        if not os.path.isdir(p):
            continue
        if name.startswith('.'):
            continue
        if name in {'__pycache__','node_modules','target'}:
            continue
        if not os.path.isfile(os.path.join(p,'AGENTS.md')):
            missing.append(f'{tech}/{name}')
print('missing_count',len(missing))
for m in missing:
    print(m)
